mkdir -p /app/output && cat > /app/output/styles.css <<'CSS'
:root {
  --navy: #0a0a23;
  --navy-2: #15152f;
  --gold: #feac32;
  --gold-soft: #fff3d9;
  --blue: #002ead;
  --ink: #111827;
  --muted: #667085;
  --line: #e7e9ee;
  --paper: #ffffff;
  --soft: #f7f8fb;
  --radius: 20px;
  --shadow: 0 22px 60px rgba(10, 10, 35, 0.08);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  color: var(--ink);
  background: var(--soft);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.6;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button, input { font: inherit; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 20;
  background: var(--navy);
  color: white;
  box-shadow: 0 4px 24px rgba(10, 10, 35, 0.18);
}
.navbar {
  max-width: 1180px;
  margin: 0 auto;
  min-height: 72px;
  display: grid;
  grid-template-columns: auto minmax(220px, 1fr) auto;
  align-items: center;
  gap: 24px;
  padding: 0 24px;
}
.logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 850;
  letter-spacing: -0.04em;
  font-size: 1.28rem;
}
.logo-mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 2px solid var(--gold);
  color: var(--gold);
  border-radius: 10px;
  font-size: 0.95rem;
}
.search {
  width: 100%;
  border: 1px solid rgba(255,255,255,0.18);
  background: rgba(255,255,255,0.1);
  color: white;
  border-radius: 999px;
  padding: 12px 18px;
  outline: none;
}
.search::placeholder { color: rgba(255,255,255,0.72); }
.nav-links { display: flex; align-items: center; gap: 8px; }
.nav-links a {
  padding: 10px 14px;
  border-radius: 999px;
  color: rgba(255,255,255,0.9);
  font-weight: 700;
  font-size: 0.94rem;
}
.nav-links a:hover, .nav-links a.active { background: rgba(255,255,255,0.13); color: white; }
.nav-links a.cta { background: var(--gold); color: var(--navy); }
.menu-toggle {
  display: none;
  background: transparent;
  color: white;
  border: 1px solid rgba(255,255,255,0.25);
  border-radius: 12px;
  padding: 9px 11px;
  cursor: pointer;
}
.menu-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  margin: 5px 0;
  background: white;
}
.mobile-menu {
  display: none;
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 24px 18px;
  border-top: 1px solid rgba(255,255,255,0.1);
}
.mobile-menu.open { display: grid; gap: 8px; }
.mobile-menu a {
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba(255,255,255,0.08);
  font-weight: 750;
}
.banner {
  background: var(--gold);
  color: var(--navy);
  text-align: center;
  font-weight: 850;
  padding: 13px 18px;
  letter-spacing: -0.01em;
}

.container { max-width: 1180px; margin: 0 auto; padding: 48px 24px; }
.section-kicker {
  color: var(--blue);
  text-transform: uppercase;
  letter-spacing: 0.13em;
  font-size: 0.78rem;
  font-weight: 900;
}
.section-title {
  font-size: clamp(2rem, 5vw, 4.6rem);
  line-height: 0.95;
  letter-spacing: -0.075em;
  margin: 12px 0 18px;
}
.section-lede { color: var(--muted); font-size: 1.1rem; max-width: 760px; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
}
.section-head h2 { font-size: clamp(1.8rem, 3vw, 2.8rem); letter-spacing: -0.055em; margin: 0; }

.featured-card {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(300px, 0.85fr);
  min-height: 440px;
  overflow: hidden;
  border-radius: 28px;
  background: var(--paper);
  box-shadow: var(--shadow);
  border: 1px solid var(--line);
}
.featured-art, .thumb {
  background:
    radial-gradient(circle at 20% 25%, rgba(254,172,50,.9), transparent 22%),
    radial-gradient(circle at 78% 35%, rgba(0,46,173,.55), transparent 24%),
    linear-gradient(135deg, #0a0a23, #27274a 48%, #f7f8fb);
  min-height: 240px;
  position: relative;
}
.featured-art::after, .thumb::after {
  content: "</>";
  position: absolute;
  right: 28px;
  bottom: 18px;
  color: rgba(255,255,255,0.75);
  font-weight: 900;
  font-size: clamp(2.6rem, 7vw, 7rem);
  letter-spacing: -0.08em;
}
.featured-body { padding: clamp(28px, 5vw, 56px); display: flex; flex-direction: column; justify-content: center; }
.tag {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  background: var(--gold-soft);
  color: #8a4f00;
  padding: 6px 10px;
  font-size: 0.78rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.tag.ai { background: #ede9fe; color: #5b21b6; }
.tag.scraping { background: #dcfce7; color: #166534; }
.tag.db { background: #e0f2fe; color: #075985; }
.tag.search-tag { background: #fee2e2; color: #991b1b; }
.tag.data { background: #ffedd5; color: #9a3412; }
.featured-body h1, .featured-body h2 { font-size: clamp(2.1rem, 4vw, 4rem); line-height: 1; letter-spacing: -0.07em; margin: 18px 0; }
.byline { display: flex; align-items: center; gap: 11px; color: var(--muted); font-weight: 700; font-size: 0.94rem; }
.avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--navy);
  color: white;
  font-weight: 900;
  border: 3px solid white;
  box-shadow: 0 0 0 1px var(--line);
  flex: 0 0 auto;
}

.article-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 22px; }
.article-card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 16px 45px rgba(10, 10, 35, 0.055);
  transition: transform .2s ease, box-shadow .2s ease;
}
.article-card:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
.article-card .thumb { min-height: 176px; }
.article-card:nth-child(2n) .thumb { background: radial-gradient(circle at 70% 25%, rgba(254,172,50,.85), transparent 22%), radial-gradient(circle at 22% 58%, rgba(0,46,173,.45), transparent 25%), linear-gradient(135deg,#111827,#394150); }
.article-card:nth-child(3n) .thumb { background: radial-gradient(circle at 23% 32%, rgba(16,185,129,.75), transparent 22%), radial-gradient(circle at 76% 50%, rgba(254,172,50,.65), transparent 22%), linear-gradient(135deg,#0a0a23,#1f2937); }
.article-body { padding: 20px; }
.article-body h3 { margin: 12px 0 22px; font-size: 1.22rem; line-height: 1.22; letter-spacing: -0.035em; }
.load-wrap { display: flex; justify-content: center; margin-top: 32px; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 999px;
  padding: 13px 22px;
  background: var(--navy);
  color: white;
  font-weight: 850;
  cursor: pointer;
  box-shadow: 0 12px 28px rgba(10, 10, 35, 0.18);
}
.btn.gold { background: var(--gold); color: var(--navy); }
.btn.ghost { background: white; color: var(--navy); border: 1px solid var(--line); box-shadow: none; }

.curriculum-hero, .donation-hero, .tag-hero {
  background: white;
  border-bottom: 1px solid var(--line);
}
.syllabus-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 16px; }
.syllabus-card, .info-card, .faq-item, .stat-card {
  background: white;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 22px;
  box-shadow: 0 12px 35px rgba(10,10,35,.045);
}
.syllabus-card { display: flex; align-items: center; gap: 16px; }
.icon {
  width: 48px;
  height: 48px;
  border-radius: 15px;
  display: grid;
  place-items: center;
  background: var(--navy);
  color: var(--gold);
  font-weight: 900;
}
.syllabus-card h3, .info-card h3 { margin: 0 0 6px; letter-spacing: -0.035em; }
.syllabus-card p, .info-card p { margin: 0; color: var(--muted); }
.three-col { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 20px; }
.link-list { display: grid; gap: 10px; margin-top: 16px; }
.link-list a { color: var(--blue); font-weight: 800; }

.donate-layout { display: grid; grid-template-columns: minmax(0, 1fr) 420px; gap: 32px; align-items: start; }
.donation-panel {
  background: white;
  border: 1px solid var(--line);
  border-radius: 28px;
  padding: 28px;
  box-shadow: var(--shadow);
  position: sticky;
  top: 96px;
}
.amount-tabs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin: 18px 0; }
.amount-tab {
  border: 1px solid var(--line);
  background: white;
  border-radius: 14px;
  padding: 14px 8px;
  font-weight: 900;
  cursor: pointer;
}
.amount-tab.active { background: var(--navy); color: var(--gold); border-color: var(--navy); box-shadow: inset 0 0 0 2px var(--gold); }
.donation-description { background: var(--gold-soft); border-radius: 16px; padding: 16px; font-weight: 750; color: #5a3600; }
.sub-label { color: var(--muted); font-size: 0.92rem; text-align: center; margin-top: 12px; }
ul.clean { padding: 0; margin: 0; list-style: none; display: grid; gap: 12px; }
ul.clean li { display: flex; gap: 10px; align-items: flex-start; }
ul.clean li::before { content: "•"; color: var(--gold); font-size: 1.5rem; line-height: 1; }
.stats-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 16px; }
.stat-card strong { display: block; font-size: 1.55rem; letter-spacing: -0.05em; color: var(--navy); }
.faq-list { display: grid; gap: 12px; }
.faq-question {
  width: 100%;
  background: transparent;
  border: 0;
  padding: 0;
  text-align: left;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  font-weight: 850;
  cursor: pointer;
  color: var(--navy);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  color: var(--muted);
  transition: max-height .28s ease, padding-top .28s ease;
}
.faq-item.open .faq-answer { max-height: 180px; padding-top: 12px; }
.faq-icon { transition: transform .25s ease; }
.faq-item.open .faq-icon { transform: rotate(45deg); }

.popular-tags { display: flex; gap: 12px; overflow-x: auto; padding: 4px 0 16px; }
.popular-tags a {
  min-width: 150px;
  background: white;
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 13px 15px;
  box-shadow: 0 10px 25px rgba(10,10,35,.04);
}
.popular-tags strong { display: block; font-size: .94rem; }
.popular-tags span { color: var(--muted); font-weight: 800; }

.footer {
  background: var(--navy);
  color: rgba(255,255,255,.82);
  margin-top: 40px;
}
.footer-grid { display: grid; grid-template-columns: 1.2fr .8fr .8fr; gap: 34px; }
.footer h3, .footer h4 { color: white; margin-top: 0; }
.footer p { margin: 0; }
.footer a { color: rgba(255,255,255,.84); }
.footer-links { display: flex; flex-wrap: wrap; gap: 9px 14px; }

@media (max-width: 900px) {
  .navbar { grid-template-columns: auto auto; justify-content: space-between; }
  .search, .desktop-nav { display: none; }
  .menu-toggle { display: block; }
  .featured-card, .donate-layout { grid-template-columns: 1fr; }
  .article-grid, .three-col, .footer-grid { grid-template-columns: 1fr 1fr; }
  .donation-panel { position: static; }
}
@media (max-width: 640px) {
  .container { padding: 36px 18px; }
  .article-grid, .syllabus-grid, .three-col, .stats-grid, .footer-grid { grid-template-columns: 1fr; }
  .section-head { display: block; }
  .featured-card { border-radius: 20px; }
  .featured-body { padding: 24px; }
  .amount-tabs { grid-template-columns: repeat(2, 1fr); }
}
